/* Câu chép chính tả: khung phát (giây) trong audio từng part, lấy theo mốc lời thoại (sync.js); chỉ giữ câu mà chữ nghe được khớp lời thoại ≥ 80%. 01/11/2026 */
window.CAMDICT={"1":{"1":[{"s":87.4,"e":91.8,"t":"You will see that there is an example that has been done for you."},{"s":102.56,"e":103.86,"t":"Oh, good morning."},{"s":104.02,"e":107.62,"t":"I'm calling on behalf of my 13-year-old son, Jacob."},{"s":107.68,"e":109.9,"t":"He's interested in learning to sail."},{"s":110.94,"e":115.16,"t":"Well, we have what we call a taster day on the 22nd of June."},{"s":115.14,"e":118.12,"t":"I'm not sure he can make it, but we'll see."},{"s":121.41,"e":125.43,"t":"the taster day. is on the 22nd of June."},{"s":126.03,"e":130.39,"t":"So 22nd June has been written in the space."},{"s":131.79,"e":133.21,"t":"Now we shall begin."},{"s":150.9,"e":153.98,"t":"I'm calling on behalf of my 13-year-old son."},{"s":154.28,"e":157.36,"t":"He's interested in learning to sail?"},{"s":158.0,"e":162.0,"t":"Well, we have what we call a taster day on the 22nd of June."},{"s":161.94,"e":165.02,"t":"I'm not sure he can make it, but we'll see."},{"s":165.3,"e":167.46,"t":"Jacob's really interested, though."},{"s":167.74,"e":169.92,"t":"So, can you tell me about the courses?"},{"s":170.8,"e":176.46,"t":"We have two types of courses for children under 16, two day and five day."},{"s":176.76,"e":178.4,"t":"Could you explain the difference?"},{"s":178.1,"e":182.58,"t":"Well, the two-day one just covers basic techniques in sailing."},{"s":183.24,"e":186.94,"t":"And on this course, the kids always sail with the instructor, they've been allocated."},{"s":187.06,"e":188.64,"t":"Well, that's good to know."},{"s":188.8,"e":191.52,"t":"Yeah, and the cost is 65 pounds."},{"s":191.82,"e":194.1,"t":"Oh, I thought it was more than that."},{"s":194.22,"e":196.72,"t":"I heard it was 125 pounds."},{"s":196.84,"e":198.58,"t":"That's for the five-day course."},{"s":198.96,"e":202.84,"t":"Okay, I presume that course goes into much more detail."},{"s":216.88,"e":220.32,"t":"I think Jacob would enjoy that course."},{"s":220.78,"e":223.66,"t":"Do you give them a certificate if they complete the course?"},{"s":225.04,"e":228.82,"t":"We give them out on the final day, which a lot of the kids really like."},{"s":229.8,"e":233.84,"t":"Could you tell me a bit more about what the children have to bring and so forth?"},{"s":234.1,"e":236.82,"t":"Well, the most important thing is the clothing is the clothing."},{"s":246.46,"e":248.3,"t":"Do they have to wear anything special?"},{"s":248.64,"e":252.12,"t":"The only rule is that they've got to have shoes of some kind."},{"s":252.08,"e":253.46,"t":"They mustn't have bare feet."},{"s":254.7,"e":259.54,"t":"And we suggest the kids pack an extra pair of trousers, you know, waterproof ones."},{"s":259.66,"e":262.32,"t":"They don't have to wear them unless it starts to rain."},{"s":267.82,"e":274.5,"t":"Oh and one other thing we do say is that the children mustn't wear jeans because they get extremely heavy when they're wet."},{"s":315.06,"e":319.22,"t":"One thing I forgot to ask is whether it's possible to get a meal anywhere."},{"s":319.56,"e":320.98,"t":"I'm afraid not."},{"s":322.1,"e":325.18,"t":"But we do have a shop. the marina stores where he can get a snack."},{"s":325.3,"e":330.16,"t":"Okay, and before I forget, when I drop Jacob off, where can I park?"},{"s":331.82,"e":334.98,"t":"There's space is near the entrance, but you have to pay for them."},{"s":335.46,"e":338.48,"t":"But there's no charge for the car park just by the bridge."},{"s":339.56,"e":341.7,"t":"Oh yes, I know where you mean."},{"s":341.88,"e":345.32,"t":"Now, we do need you to fill in a registration form."},{"s":345.02,"e":348.92,"t":"You should send that in a couple of weeks before the course starts."},{"s":349.36,"e":353.5,"t":"The form is on the website, but we ask you to print it off and add your signature."},{"s":355.2,"e":357.2,"t":"What sort of information do you need?"},{"s":357.52,"e":362.82,"t":"About your child swimming ability, any special requirements and so on?"},{"s":362.72,"e":365.1,"t":"Will you need to know who his doctor is?"},{"s":366.2,"e":370.12,"t":"We've just recently changed surgeries surgeries, so I'll make a note to get that."},{"s":370.36,"e":372.08,"t":"and one more thing."},{"s":371.78,"e":379.88,"t":"There's a separate form on the website, which is optional, that asks whether you're willing for photographs to be taken during the course."},{"s":379.96,"e":381.66,"t":"Yes, of course, no problem."},{"s":382.74,"e":384.28,"t":"So, um, I'll send you..."}],"2":[{"s":63.22,"e":64.98,"t":"My name's Mark Bergen."},{"s":75.72,"e":84.38,"t":"The company has 225 department stores and owns a further 150 supermarkets."},{"s":84.82,"e":93.88,"t":"At our latest store opening we had over 9,000 applicants for 750 posts."},{"s":94.56,"e":98.46,"t":"So why do so many people want to work for us?"},{"s":98.76,"e":105.74,"t":"Well, the first thing that attracts them isn't so much the salary, although that is a little above average."},{"s":105.98,"e":115.54,"t":"It's the idea of getting a massive 25% off everything from washing machines to designer handbags."},{"s":115.86,"e":119.94,"t":"People are prepared to put in long hours to get those kinds of perks."},{"s":120.92,"e":129.56,"t":"Johnson Jones has been going strong for nearly 150 years and has outlived many of its strongest competitors."},{"s":141.86,"e":144.06,"t":"But we're not alone in that."},{"s":144.36,"e":148.96,"t":"Where we are different is in our approach to making a profit."},{"s":148.66,"e":158.78,"t":"Other companies think in the short term, whereas we always take a more strategic view, looking three or five years ahead."},{"s":159.18,"e":163.54,"t":"The company isn't owned by a family or shareholders."},{"s":163.86,"e":173.58,"t":"It's a partnership, which means it's owned by its full-time employees, who are all partners and have a share in the company."},{"s":173.28,"e":183.14,"t":"In return for the very generous benefits they get, they're expected to put in extra effort and take an active role in running the company."},{"s":183.56,"e":189.48,"t":"This means they're involved in things like making decisions about pension contributions, for example."},{"s":190.4,"e":198.24,"t":"Another very attractive reason for working for us is the annual bonus, which we get as a percentage of our salary."},{"s":198.32,"e":204.88,"t":"Last year it was 15 percent, about two months salary, which is a pretty standard."},{"s":219.48,"e":226.08,"t":"The most popular benefit for partners are the subsidised holiday centres which are owned by the company."},{"s":226.64,"e":230.38,"t":"Once a year partners can book in for up to two weeks."},{"s":230.66,"e":233.56,"t":"It's for anyone from cleaners to directors"},{"s":233.28,"e":236.44,"t":"with a minimum of three months service."},{"s":236.82,"e":242.1,"t":"After six months service, partners are entitled to a further subsidy on the cost of their stay."},{"s":285.04,"e":289.54,"t":"Let me just give you an idea of what's on offer at the holiday centers."},{"s":300.5,"e":304.32,"t":"It's all very informal, not like a normal conference centre."},{"s":305.02,"e":313.1,"t":"Meadow House is located in Kent, which is famous for its apples and other fruit, and it's a large country house."},{"s":313.38,"e":319.36,"t":"What's unusual about it is that, unlike other hotels, you have access to the kitchen."},{"s":319.24,"e":322.12,"t":"So it feels more like staying with a friend."},{"s":322.88,"e":325.9,"t":"Koom Manner is a working farm."},{"s":326.16,"e":332.26,"t":"There are loads of cows and sheep, none of which actually end up on our supermarket shelves."},{"s":332.36,"e":339.58,"t":"It's a paradise for kids, as there's plenty of space to run wild and also an indoor pool."},{"s":340.06,"e":343.92,"t":"You can choose to stay in cottages or camp by the lake."},{"s":344.6,"e":350.7,"t":"The barn is where I recently celebrated my 25th wedding anniversary."},{"s":351.1,"e":355.86,"t":"You can rent the whole place out for a large group of up to 40 friends."},{"s":356.0,"e":363.36,"t":"We got all our food delivered from the nearest Johnson Jones supermarket, so there was no cooking to be done."},{"s":364.6,"e":369.5,"t":"All that was missing was the spa, which should be opening next year."},{"s":369.96,"e":374.56,"t":"The stable is often hard to get into because it's so popular."},{"s":374.82,"e":379.38,"t":"That's partly because it's right on the beach with beautiful sea views."},{"s":379.24,"e":382.36,"t":"and only an hour by train from London."},{"s":384.68,"e":392.22,"t":"The company Sailing Club is located there which was started by the company's founder in 1885."},{"s":392.78,"e":395.88,"t":"So I'm sure you'll all agree that there really is..."}],"3":[{"s":27.02,"e":33.14,"t":"Right, now you wanted to organize a formal discussion of some sort in the class, is that right, Daniel?"},{"s":33.28,"e":39.04,"t":"Yes, we thought it would be really good to end our psychology course with a formal debate."},{"s":39.42,"e":43.72,"t":"You know, where there's a statement and people argue for or against it."},{"s":44.8,"e":47.18,"t":"Where did the enthusiasm come from?"},{"s":47.5,"e":50.0,"t":"Have either of you organized debates before?"},{"s":65.38,"e":69.88,"t":"So what do you think the students you and the others would get out of this?"},{"s":81.66,"e":87.44,"t":"Sometimes you kind of don't know what you truly believe until you hear something you disagree with."},{"s":87.38,"e":90.26,"t":"Okay what about the topic for the debate?"},{"s":90.62,"e":92.74,"t":"We've got three to choose from."},{"s":92.8,"e":95.1,"t":"We'll show you in a minute to check they're okay."},{"s":95.54,"e":102.5,"t":"At first we thought we'd asked the other students to suggest something, but we were afraid would get 30 different topics."},{"s":102.92,"e":110.46,"t":"So instead we brainstormed some, just the two of us then made a short list and we'll one they like best."},{"s":111.24,"e":116.12,"t":"But the thing is, if people don't know how debates work, they could feel it a disadvantage."},{"s":116.66,"e":120.36,"t":"I mean, it wouldn't affect their grades or anything, but it could put them off."},{"s":129.04,"e":130.68,"t":"I think that's a good idea."},{"s":147.06,"e":152.48,"t":"We think it'll be best if we can use an issue that the students already have strong opinions about."},{"s":152.34,"e":157.38,"t":"Then some people will be happy to speak in support of it and others to oppose it."},{"s":158.5,"e":160.92,"t":"What else do you want to do at the meeting?"},{"s":161.14,"e":165.96,"t":"Well, we've got to think about how people will do the background research for the debate."},{"s":166.42,"e":171.56,"t":"We could organize everyone into two teams That should save time for the main speakers."},{"s":171.66,"e":173.36,"t":"They won't have to do it on their own."},{"s":184.0,"e":188.04,"t":"Now I think you should have some sort of follow-up to the debate."},{"s":188.5,"e":195.44,"t":"After it's over, I'd like you to get everyone to write a short essay, focusing on what they gain from participating in. it."},{"s":195.96,"e":200.72,"t":"And in turn, that can feed into the work we've been doing on learning and motivation."},{"s":200.76,"e":204.54,"t":"But would you be willing to read them and report back?"},{"s":204.6,"e":206.74,"t":"I mean, give some feedback on them."},{"s":206.72,"e":209.1,"t":"I wouldn't have made the suggestion if I wasn't."},{"s":250.36,"e":255.8,"t":"You need to decide exactly how you'll introduce the students to different features of a debate."},{"s":256.0,"e":260.96,"t":"Well, first of all, we need to inform everyone about what actually happens at a debate."},{"s":261.18,"e":262.96,"t":"The procedures and so on."},{"s":263.38,"e":266.76,"t":"We could talk about that and write the main information on the board."},{"s":266.64,"e":272.32,"t":"Or instead of that, we could make a summary of the main stages and hand that out."},{"s":272.02,"e":273.8,"t":"Then talk it through."},{"s":274.46,"e":276.02,"t":"Yes, okay, that's better."},{"s":276.32,"e":280.94,"t":"Okay, but we do need to talk about body language as well."},{"s":281.0,"e":283.38,"t":"Yes, that's a very important tool."},{"s":283.76,"e":289.92,"t":"I've got an interesting article on that with some good diagrams of techniques for things like eye contact."},{"s":290.36,"e":292.44,"t":"I'll make some copies for you to give out."},{"s":292.98,"e":297.18,"t":"Then we need to think about where people will find the information on the debate topic."},{"s":296.88,"e":300.12,"t":"So they'll need to know where to look for the information."},{"s":300.78,"e":304.8,"t":"We could compile a list of sources, textbooks and articles and so on."},{"s":304.78,"e":310.96,"t":"We could, but couldn't people offer their own suggestions and advice on that at the meeting instead?"},{"s":310.9,"e":313.1,"t":"Yes, get everyone involved."},{"s":314.18,"e":318.16,"t":"What about preparation for asking and answering questions?"},{"s":318.54,"e":322.5,"t":"We could try to demonstrate that, but I'm not sure how."},{"s":322.64,"e":326.0,"t":"Maybe we could put up a list of points on the board."},{"s":327.28,"e":329.82,"t":"Yes, that sounds better, thanks."},{"s":329.8,"e":332.28,"t":"Okay, well, let's meet up again."}],"4":[{"s":88.83,"e":96.65,"t":"I will talk about a theory that tells crisis managers how to communicate in different kinds of crises."},{"s":97.61,"e":102.69,"t":"Some people ask why we need theory in crisis communication."},{"s":102.39,"e":105.41,"t":"Isn't logic the answer?"},{"s":106.19,"e":108.19,"t":"Yes, it is sometimes."},{"s":108.85,"e":113.49,"t":"But organizations often handle crisis communication badly."},{"s":114.19,"e":124.63,"t":"What we find is that in reality, much of the advice that organizations receive on how to respond to a crisis is just a guess."},{"s":124.89,"e":131.31,"t":"Theory and research allow us to take those suggestions and test them."},{"s":131.01,"e":139.71,"t":"Then managers can be given advice based on actual evidence of what works and what doesn't."},{"s":140.99,"e":146.45,"t":"The crisis theory has categorized three general types of crises."},{"s":147.57,"e":154.85,"t":"One type is a crisis where the organization is a victim and has very little responsibility."},{"s":156.05,"e":160.91,"t":"For example, this kind of crisis could be caused by a rumor."},{"s":161.01,"e":164.47,"t":"The second kind is accidental."},{"s":164.99,"e":172.27,"t":"There isn't much responsibility because there are other outside factors that contributed to it."},{"s":173.03,"e":179.71,"t":"And the third one, and the most difficult to actually manage, is a preventable crisis."},{"s":180.17,"e":188.51,"t":"In this kind of crisis, those affected believe strongly that a mistake was made within the organization."},{"s":191.01,"e":200.51,"t":"is important because the more people think the organization is responsible for the crisis, the angrier they become at the organization."},{"s":201.71,"e":210.01,"t":"The theory begins by suggesting a two-part basic response that can be used in all kinds of crisis."},{"s":210.73,"e":219.15,"t":"The first part is to provide information to those affected so that they can protect themselves from further harm."},{"s":219.63,"e":223.05,"t":"Many crises pose a risk to people."},{"s":223.49,"e":229.57,"t":"For example, if there is a chemical release, people might have to evacuate an area."},{"s":241.81,"e":252.11,"t":"The second part of the basic response is to communicate the action the organization is planning, in order to prevent another crisis."},{"s":252.85,"e":260.95,"t":"This is important because those affected by a crisis are often concerned that it is going to happen again."},{"s":265.66,"e":273.26,"t":"Beyond this, crisis managers also have other tools to shape how people think about the crisis."},{"s":273.62,"e":278.18,"t":"Crisis managers can use several strategies to do this."},{"s":278.66,"e":281.8,"t":"One strategy is to diminish the crisis."},{"s":281.5,"e":291.58,"t":"If crisis managers have proof, which is convincing, they can argue that a crisis is not as bad as people think."},{"s":292.22,"e":297.54,"t":"If they can argue this successfully, the harmful effects are reduced."},{"s":298.54,"e":305.16,"t":"Another way to shape thinking is to give excuses which emphasize a lack of intent."},{"s":305.86,"e":309.78,"t":"Therefore, people will see the crisis as an accident."},{"s":309.48,"e":319.12,"t":"This is important because an accidental crisis is much easier to manage than an intentional crisis."},{"s":319.72,"e":327.62,"t":"Crisis managers can also protect the organization's reputation when there is a major crisis."},{"s":328.32,"e":334.42,"t":"Their first goal is to reduce the negative opinions generated by the crisis."},{"s":378.16,"e":384.14,"t":"Rebuild strategies can also be used to reduce the impact of the crisis."},{"s":383.86,"e":392.32,"t":"To do this, crisis managers say and do things to benefit those affected by the crisis."},{"s":394.12,"e":399.28,"t":"The reputation of the organization can also be protected in practical ways."},{"s":399.94,"e":406.58,"t":"The problem can sometimes be addressed by offering an apology to those affected by the crisis."},{"s":407.86,"e":412.78,"t":"This may be sufficient action when the problem is relatively minor."},{"s":413.58,"e":423.72,"t":"However, if the crisis is very severe, the most common strategy is to offer compensation to those affected. to those affected."},{"s":424.12,"e":434.48,"t":"To summarize, crisis communication theory is interesting to managers as it gives positive guidance on how to respond."},{"s":435.36,"e":438.7,"t":"It can help them figure out which strategy is."}]},"2":{"1":[{"s":85.86,"e":88.56,"t":"Hello, Creative Center."},{"s":90.14,"e":94.64,"t":"I'm phoning to book a place on your next two-day drama workshop."},{"s":96.18,"e":97.72,"t":"Let me just check."},{"s":99.37,"e":101.81,"t":"Yes, we've still got room on that course."},{"s":103.59,"e":105.15,"t":"Can I have your full name?"},{"s":108.59,"e":113.59,"t":"Uh, that's C-R-E-S-W-I-C-K."},{"s":115.31,"e":117.17,"t":"And are you coming on your own?"},{"s":118.53,"e":121.31,"t":"And have you done any of our courses before?"},{"s":121.31,"e":124.21,"t":"Yes, I did one a couple of years ago."},{"s":125.49,"e":128.37,"t":"So you may be on our computer records."},{"s":128.49,"e":130.51,"t":"Which course did you do?"},{"s":130.59,"e":133.11,"t":"The writing for the theater course?"},{"s":137.07,"e":140.31,"t":"Oh, so that's 20 Gregory Avenue."},{"s":141.31,"e":143.05,"t":"Gregory place, actually."},{"s":143.29,"e":146.05,"t":"Okay, I'll correct that on the computer."},{"s":147.87,"e":149.89,"t":"And can I ask if you work?"},{"s":150.21,"e":155.55,"t":"Yes, I want to be an actor, but I'm working as a waitress at the moment."},{"s":155.75,"e":157.59,"t":"After this course, who knows?"},{"s":158.21,"e":160.21,"t":"Right, back to the paperwork."},{"s":160.67,"e":166.33,"t":"So, we're enrolling you on the two-day course that starts tomorrow, the 30th of May."},{"s":168.25,"e":170.41,"t":"No, on the 13th of June."},{"s":170.75,"e":172.93,"t":"I meant the one starting in two weeks."},{"s":173.27,"e":174.71,"t":"Is that still all right?"},{"s":174.61,"e":176.13,"t":"Oh, that's fine."},{"s":217.33,"e":219.49,"t":"Can you tell me something about accommodation?"},{"s":221.13,"e":224.51,"t":"People usually come the evening before the course starts."},{"s":224.89,"e":228.13,"t":"The cost of the course includes accommodation. for two nights."},{"s":228.23,"e":234.59,"t":"Well, I'll make sure I'm there in good time so I can meet the others that evening and settle in."},{"s":234.75,"e":237.25,"t":"Is 5.30 too early to arrive?"},{"s":237.39,"e":238.87,"t":"No, that's fine."},{"s":239.37,"e":242.57,"t":"And you'll finish no later than 5 o'clock on the last day?"},{"s":246.03,"e":248.03,"t":"Just a few other things."},{"s":248.33,"e":255.75,"t":"Any dietary information we should know, all the food is provided, and we use organic produce as often as we can."},{"s":255.97,"e":257.63,"t":"Oh, that sounds great."},{"s":257.87,"e":260.75,"t":"But I don't eat anything that's made from milk."},{"s":261.11,"e":263.21,"t":"I know that can be difficult."},{"s":265.39,"e":266.81,"t":"What about meat?"},{"s":267.73,"e":270.77,"t":"I don't need much of it, but that's fine."},{"s":270.91,"e":272.37,"t":"You don't need to note that."},{"s":274.89,"e":277.93,"t":"Hey, I am really looking forward to this."},{"s":287.73,"e":293.29,"t":"If we do that, there'll be a choice of doing comic, or what we call classic work."},{"s":292.99,"e":296.23,"t":"Oh, I'd always go with comedy."},{"s":296.49,"e":298.45,"t":"I'm much more interested in that."},{"s":299.37,"e":302.61,"t":"Now, how did you find out about this course?"},{"s":302.97,"e":305.13,"t":"Was it the adverts in the Sunday newspaper?"},{"s":306.57,"e":311.77,"t":"In fact, I looked for drama courses on the internet, and I saw that you were doing one."},{"s":311.91,"e":315.13,"t":"When I read about it, I just thought, hey, why not?"},{"s":315.67,"e":319.89,"t":"I saw that you send out some pre-course material."},{"s":329.77,"e":331.71,"t":"I'll put a copy in the post here."}],"2":[{"s":55.22,"e":59.08,"t":"Well, hello everyone and welcome to Parsons Fruit Farm."},{"s":59.54,"e":64.92,"t":"It's good to see a mix of so many different nationalities who have all come here on their working holidays."},{"s":69.12,"e":72.3,"t":"First of all, just a few words about accommodation."},{"s":73.2,"e":78.34,"t":"I know that some of you have pitched your tents down at the campground, but are looking for something more comfortable."},{"s":79.16,"e":81.48,"t":"So one option is the motel."},{"s":82.1,"e":88.6,"t":"It's located very conveniently, just a few minutes away, and they often do reduce rates if you're staying long-term."},{"s":89.12,"e":94.88,"t":"And then the backpackers' hostel is always very popular, though it can be busy at this time of year."},{"s":96.86,"e":99.1,"t":"So, the work itself."},{"s":99.88,"e":102.32,"t":"This summer the weather's been pretty mixed."},{"s":102.5,"e":106.32,"t":"We've had a bit of everything and the forecasts have always been wrong."},{"s":106.86,"e":110.04,"t":"So some of the apples and pears aren't in great condition."},{"s":110.76,"e":114.7,"t":"That said, this season's been better than some we've had recently."},{"s":115.1,"e":117.54,"t":"And the autumn looks like it's going to be great."},{"s":117.8,"e":120.62,"t":"So we should have ideal conditions for the harvest."},{"s":121.96,"e":125.06,"t":"So, there are a number of different jobs to do."},{"s":125.28,"e":126.92,"t":"Most of you will be fruit picking."},{"s":127.32,"e":132.14,"t":"We'll give all the fruit pickers gloves to wear to protect your fingers so you won't hurt yourselves."},{"s":133.42,"e":136.24,"t":"We'll also be looking for some tractor drivers."},{"s":136.78,"e":141.82,"t":"Their job is to collect the full baskets of fruit and take them to the shed."},{"s":142.22,"e":151.84,"t":"I should say, in this country, anyone is allowed to drive a tractor on farmland once they're 13, rather than 18 as in some countries."},{"s":152.88,"e":157.56,"t":"However, we do have certain rules that are specific to our farm."},{"s":158.26,"e":160.78,"t":"You don't need to have done farm work before."},{"s":161.12,"e":167.7,"t":"But here you must have a relevant document or permit from your country that allows you to operate this type of vehicle."},{"s":169.06,"e":172.98,"t":"Then there are also lots of jobs working inside the shed."},{"s":173.38,"e":176.8,"t":"This involves sorting the fruit and cleaning it if necessary."},{"s":176.5,"e":183.96,"t":"There's a lot of heavy machinery in the shed so when that's operating you must wear your ear protection."},{"s":184.84,"e":191.46,"t":"The big advantage is the shed's fully air conditioned so it's a pleasant environment regardless of what the weather's doing outside."},{"s":192.78,"e":198.02,"t":"All right well whatever job you do I'll just give you some final advice."},{"s":199.0,"e":204.58,"t":"When you're picking the fruit sometimes you can break off a small branch."},{"s":204.84,"e":206.62,"t":"That's not something you need to be worried."},{"s":206.98,"e":208.98,"t":"It'll grow back."},{"s":209.52,"e":213.36,"t":"Also, remember to have snacks and use your water bottles often."},{"s":213.66,"e":217.2,"t":"People get exhausted quickly during harvest time."},{"s":217.84,"e":223.38,"t":"And if you've got a mobile or cell, keep it with you at all times, in case there's an emergency."},{"s":265.03,"e":269.33,"t":"All right, I'd like to quickly go over where everything is located."},{"s":269.39,"e":274.63,"t":"So look at your maps of Parson's fruit farm and find the main yard."},{"s":274.65,"e":276.89,"t":"It's towards the bottom of your maps."},{"s":277.83,"e":280.29,"t":"That really is the centre of the farm."},{"s":280.99,"e":285.11,"t":"Okay, the first place I'll mention is the workshop."},{"s":284.81,"e":287.69,"t":"This is close to the main yard."},{"s":288.37,"e":291.89,"t":"But you actually have to leave the yard to get into it."},{"s":292.07,"e":298.37,"t":"So you need to take the road that goes out to the orchards and you access the workshop from there."},{"s":299.27,"e":300.85,"t":"Then the lunchroom."},{"s":301.29,"e":306.91,"t":"On the north side of the map there's a road that curves sharply round to the left."},{"s":307.37,"e":311.35,"t":"Halfway around this bend you'll find the entrance to the lunchroom."},{"s":311.67,"e":315.65,"t":"It's a pretty place next to the river and also beside the road. little wood."},{"s":317.31,"e":320.77,"t":"You also need to be able to find the farm office."},{"s":321.27,"e":327.31,"t":"So, if you look at the main yard, you'll see there's a number of different buildings located around it."},{"s":327.23,"e":330.27,"t":"And the farm office is the smallest one."},{"s":332.97,"e":335.79,"t":"Obviously, the first aid room is important."},{"s":336.55,"e":340.33,"t":"Now, this is close to the main yard, so it's quick to get there."},{"s":340.43,"e":344.07,"t":"And it's actually more or less in the middle of your maps."},{"s":348.33,"e":349.77,"t":"Then the store shed."},{"s":350.21,"e":352.91,"t":"From the main yard take the road heading north."},{"s":353.03,"e":355.25,"t":"Go past the farmhouse and turn right."},{"s":355.67,"e":357.59,"t":"The store is down that road."},{"s":358.23,"e":361.65,"t":"If you come to the vegetable gardens, you've gone too far."},{"s":362.93,"e":366.49,"t":"Now the other thing is the farmhouse is further than you'd expect."}],"3":[{"s":57.6,"e":63.6,"t":"Hi Scott, here are my notes."},{"s":64.06,"e":66.1,"t":"Let's sort this presentation out then."},{"s":66.42,"e":70.62,"t":"The first thing I found out about Stone Point is it's an extinct volcanic cone."},{"s":70.6,"e":72.94,"t":"You probably know that already being in New Zealander?"},{"s":72.76,"e":77.3,"t":"Yes, and there are two other cones nearby, which also overlook the harbour."},{"s":78.5,"e":85.68,"t":"Yeah, the first settlers of New Zealand, the Maori, sailed to New Zealand thousands of years after these volcanoes erupted."},{"s":90.36,"e":93.0,"t":"points significant historical role."},{"s":93.18,"e":100.98,"t":"It's been used by both Maori and European settlers as a place to shelter from attack or launch in attack for centuries."},{"s":101.38,"e":107.04,"t":"Yeah, and the fact it was an ideal place for building a village, it would have been quite a sheltered spot."},{"s":107.6,"e":112.6,"t":"I suppose the Maori settled there because they thought the volcanic soil would help their crops grow."},{"s":113.14,"e":120.14,"t":"Well, they would have realised the benefits of the soil after a few good harvest, but initially the fishing opportunities would have been the attraction."},{"s":122.22,"e":126.56,"t":"Actually, I also read that Maori regards Stone Point as Talna?"},{"s":127.02,"e":129.34,"t":"I believe that means a treasured thing."},{"s":129.5,"e":133.06,"t":"Well, your Maori vocabulary is improving, Scotch."},{"s":134.08,"e":138.34,"t":"We do have to deal with Stone Point's cultural value for Maori."},{"s":138.54,"e":141.32,"t":"That's still part of its historical significance."},{"s":141.84,"e":145.68,"t":"But we need to keep most Maori terminology out of the presentation."},{"s":146.0,"e":150.26,"t":"Otherwise, a lot of the international students won't be able to follow us."},{"s":150.32,"e":152.68,"t":"That's a shame, I'm sure they'd be interested."},{"s":161.14,"e":165.5,"t":"Anyway, European migrants turned Stone Point into a lookout point for ships."},{"s":165.6,"e":173.18,"t":"Then it became a fort, an army base in the late 1880s, and then during the World Wars, the fort was modernised again."},{"s":173.36,"e":176.2,"t":"It's also been a public park sometimes."},{"s":176.52,"e":180.8,"t":"I'd prefer to devote more of the presentation to the military use of Stone Point."},{"s":181.4,"e":184.3,"t":"There are some great websites about the engines they installed."},{"s":185.02,"e":188.82,"t":"Sorry, I wouldn't go into the technical side if I were you."},{"s":189.2,"e":193.24,"t":"If you start describing mechanical stuff, people will switch off."},{"s":193.22,"e":199.16,"t":"I think it's more interesting to look at the impact Stone Point had on the people's lives at the time."},{"s":198.86,"e":208.32,"t":"I mean, for example, there were about 25 years when they used local prisoners to build the tunnels and the underground rooms."},{"s":208.62,"e":209.96,"t":"They lived there too."},{"s":210.48,"e":213.8,"t":"Yeah, I guess, if we can find some first-hand accounts."},{"s":262.8,"e":266.26,"t":"Okay, so let's make a checklist of things to do."},{"s":276.24,"e":277.78,"t":"Yes, that needs work."},{"s":293.26,"e":297.88,"t":"We should add some more information about what it was the prisoners were adding to it."},{"s":297.62,"e":300.08,"t":"Okay, I'll do that bit too."},{"s":306.9,"e":311.7,"t":"I mean, that's a bit where we have the most visible evidence of historic buildings."},{"s":312.46,"e":317.56,"t":"I'll ring the Department of Conservation and see if they'll agree to let me film the site."},{"s":318.14,"e":321.62,"t":"Maybe allow me access to some of the tunnels or public don't see."},{"s":322.54,"e":330.14,"t":"for the 1950s onwards could you also arrange a meeting with someone from the Department of Conservation to ask them about their restoration work?"},{"s":331.36,"e":335.16,"t":"Oh and just about its use as a public park today."},{"s":335.46,"e":337.04,"t":"Where is the boundary exactly?"},{"s":337.26,"e":339.22,"t":"Does it go all the way to the beach?"},{"s":340.24,"e":341.94,"t":"I'll check that out. great."},{"s":342.74,"e":348.3,"t":"I suppose it would finish off the presentation nicely if we explain the future plans for the site."}],"4":[{"s":73.08,"e":79.44,"t":"As you know, the world is running out of fossil fuels, that is crude oil, coal and natural gas."},{"s":79.14,"e":87.54,"t":"As an alternative, certain plants are now being considered as biofuels, which are fuels made from organic plant material."},{"s":87.94,"e":92.32,"t":"These are possible sources of energy once the fossil fuels have gone forever."},{"s":96.66,"e":101.7,"t":"It was first a native of Central America, and it's now found across the world."},{"s":102.08,"e":109.02,"t":"A few things that make this plant especially attractive is that it can survive in very poor quality soil."},{"s":109.14,"e":114.74,"t":"As it does, for example, alongside train tracks in India, on the line between Mumbai and Delhi."},{"s":115.42,"e":119.16,"t":"And for up to three years, it's resistant to drought."},{"s":119.26,"e":122.5,"t":"That's right, it can do without rain for that long."},{"s":123.08,"e":129.92,"t":"And even if it's not actually a plant that people can eat, it's still worth having it on your land, as it prevents erosion."},{"s":130.28,"e":133.46,"t":"And we looked at the dangerous consequences of that in a previous lecture."},{"s":144.96,"e":153.26,"t":"After processing, the seeds can yield up to four times the oil that soybean can and ten times the amount compared to corn."},{"s":153.56,"e":155.92,"t":"So you can see why it's causing such interest."},{"s":156.26,"e":159.84,"t":"And not much is wasted in the processing procedure either."},{"s":173.06,"e":180.96,"t":"Also, whereas our fossil fuels cannot be replaced, the energy produced by biofuels such as jatropha is renewable."},{"s":181.16,"e":184.66,"t":"It's not going to run out because the plants just go on growing."},{"s":189.73,"e":195.11,"t":"There's no doubt that it is a remarkable plant and one that has been very beneficial to men."},{"s":195.43,"e":201.45,"t":"In various African communities, it's been used to operate water pumps and refrigerate medicines."},{"s":201.99,"e":209.89,"t":"It can be used to produce candles or as a fencing plant to keep some animals enclosed and some animals out."},{"s":224.31,"e":231.81,"t":"Anyway, that's not what the European corporations who are buying vast amounts of land for jatropha plantations are focusing on."},{"s":267.59,"e":272.23,"t":"But not everyone shares the excitement over jatropha, nor other biofuels."},{"s":285.91,"e":293.25,"t":"Furthermore, skeptics also point out that as there are many species of jatropha, its oil productivity is unreliable."},{"s":293.89,"e":304.21,"t":"Aside from this, critics of jatropha and other biofuels claim that farmers now have a strong economic incentive to grow them rather than food crops."},{"s":317.03,"e":320.05,"t":"There's also the concern over environmental damage."},{"s":335.63,"e":342.21,"t":"You can also imagine that such deforestation makes a considerable contribution to global warming."},{"s":343.45,"e":349.09,"t":"Furthermore, opponents also reject the idea that biofuels are a carbon-neutral source of energy."}]},"3":{"1":[{"s":96.55,"e":98.37,"t":"Thank you for calling Getaway Tours."},{"s":99.75,"e":101.09,"t":"How can I help you today?"},{"s":102.25,"e":106.53,"t":"I've got a lot of questions, but can you first tell me your office hours?"},{"s":107.45,"e":110.55,"t":"We're open from 10 a.m. to 7 p.m."},{"s":111.97,"e":118.75,"t":"I saw your article in my favorite magazine last month, and I'd like more information about the different tours."},{"s":118.75,"e":122.27,"t":"We have gotten a lot of calls about that article."},{"s":122.29,"e":123.67,"t":"I'm not surprised."},{"s":124.09,"e":129.93,"t":"Is it true that if I book a tour, the prices start at only $1,100 per person?"},{"s":130.15,"e":133.81,"t":"Yes, that's a special offer for this month."},{"s":133.95,"e":139.27,"t":"Normally, they're from $1,400 going up to $2,000."},{"s":138.97,"e":143.39,"t":"dollars and it includes accommodation and meals."},{"s":143.87,"e":148.37,"t":"This offer is for any of our 36 different bicycling tours."},{"s":148.45,"e":154.21,"t":"Well I am definitely interested in the bicycling tours but I thought there were only 30."},{"s":154.61,"e":156.21,"t":"Are all of them for a week?"},{"s":158.03,"e":163.47,"t":"If bicycling is not your thing we also have walking tours to choose from."},{"s":163.35,"e":164.91,"t":"That's a lot of options."},{"s":165.27,"e":168.39,"t":"Are you aware that our trips all begin on Tuesday?"},{"s":170.37,"e":172.15,"t":"It would give me Monday to pack."},{"s":172.93,"e":176.15,"t":"How do you suggest I choose from so many options?"},{"s":176.11,"e":178.79,"t":"Yes, it is tough to make a choice."},{"s":179.03,"e":181.95,"t":"I would love to hear about your most popular tours."},{"s":229.34,"e":231.44,"t":"great shape for a hard ride."},{"s":231.68,"e":234.46,"t":"Do you have rides that are at the beginning or level?"},{"s":235.74,"e":238.0,"t":"There's our Florida trip."},{"s":238.14,"e":239.92,"t":"That's 14 nights."},{"s":240.26,"e":249.08,"t":"But I'd recommend our holiday on the east coast of the U.S. in an area known as the Autumn Route, which is just six nights."},{"s":249.54,"e":258.98,"t":"With short leisurely routes on trails by the riverside and through the forest, you have plenty of time to explore the landscape during your holiday."},{"s":260.4,"e":263.82,"t":"Seeing the changing colors of the leaves would be amazing."},{"s":263.94,"e":265.7,"t":"Yes, that's right."},{"s":266.04,"e":272.4,"t":"You also have the option to stop at some outstanding homes and to see their gardens."},{"s":284.38,"e":287.92,"t":"Could you tell me about one of your moderate rides?"},{"s":289.54,"e":292.8,"t":"Maybe my wife and I will get into enough shape to be able to do one."},{"s":292.94,"e":294.88,"t":"Well, let me see."},{"s":295.22,"e":298.38,"t":"Oh, this trip is actually 10 nights long."},{"s":298.78,"e":301.78,"t":"It travels through parts of Southern California."},{"s":302.3,"e":308.84,"t":"The ride begins on a mountain trail, and finally brings you down to the coastal roads."},{"s":308.54,"e":311.72,"t":"Oh yes, I see that here on your website."},{"s":311.96,"e":314.38,"t":"Oh, that looks amazing!"},{"s":314.74,"e":319.0,"t":"I like that we would have the opportunity to try some of the local cuisine."},{"s":318.94,"e":325.32,"t":"Yes, the cuisine in this area makes lavish use of colorful local produce."},{"s":325.7,"e":332.32,"t":"And then, you know, the great weather of this region is a great feature by itself."},{"s":332.38,"e":334.8,"t":"Do we stay in hotels on this trip?"},{"s":334.5,"e":338.32,"t":"You stay in hotels most of the way until the end."},{"s":338.56,"e":341.46,"t":"When you stay on a farm overlooking the sea."},{"s":341.84,"e":343.82,"t":"That's always really popular."},{"s":345.1,"e":347.04,"t":"Both trips sound fabulous!"},{"s":347.64,"e":350.54,"t":"How far in advance do I have to make reservations?"}],"2":[{"s":54.08,"e":57.26,"t":"Good evening parents and thank you for offering your help."},{"s":57.8,"e":61.78,"t":"I'm here to talk about the sports programs that the children are taking part in this term."},{"s":72.16,"e":77.04,"t":"First up, we're looking for parents who would like to become team coaches or managers."},{"s":77.64,"e":82.04,"t":"We had some excellent people last year, but some of those parents now have other commitments."},{"s":82.68,"e":89.88,"t":"It's the Year 4 netball team, the year 5 and 6 rugby teams, and the Year 3 hockey team that need new people."},{"s":92.84,"e":99.88,"t":"I know some parents might not be completely familiar with, say, rugby or netball rules, but don't let that put you off."},{"s":100.42,"e":107.3,"t":"Obviously, knowledge of the game helps, but if you're keen, there are some coaching courses you can take before the training sessions for players begin."},{"s":107.8,"e":110.2,"t":"And these also get held throughout the whole season."},{"s":110.84,"e":113.72,"t":"What's really required is the right attitude."},{"s":114.04,"e":117.5,"t":"Are you the kind of person that can motivate kids and make the game seem exciting?"},{"s":118.46,"e":122.58,"t":"All the rugby training and matches are organised by North Shore Rugby Club."},{"s":122.92,"e":128.14,"t":"If you do volunteer to become a rugby coach, you'll need to go along to an important day that's coming up."},{"s":128.28,"e":130.88,"t":"That's on Saturday the 23rd."},{"s":140.28,"e":144.9,"t":"Matches are on Saturday morning and training sessions on a Wednesday after school."},{"s":145.54,"e":149.08,"t":"Moving on to netball, matches and uniforms."},{"s":149.62,"e":155.54,"t":"Matches are on Monday at 4pm and take place at the North Harbour netball grounds."},{"s":213.63,"e":218.33,"t":"Okay, some viewer kindly helping with the cross-country running event."},{"s":219.17,"e":225.29,"t":"Children in years 3 to 6 will be running from school at the bottom of your map there."},{"s":225.45,"e":231.55,"t":"The route isn't marked on your map I'm afraid, but I'm going to point out some different places that need parent supervision."},{"s":232.31,"e":233.93,"t":"The drink station is one."},{"s":244.41,"e":250.79,"t":"Two or three parents will be needed to help out at the major crossing point just to make sure everybody's going the right way."},{"s":251.43,"e":258.99,"t":"So on the map there's that little footpath going up past the school then it splits into three directions."},{"s":259.59,"e":266.49,"t":"The crossing point is at the end of the left-hand path heading west just before you cross summer street."},{"s":267.39,"e":272.25,"t":"Now we'll need a couple of parents at the half-way point to send the children in the right direction."},{"s":273.13,"e":276.35,"t":"So there are four buildings on the far left-hand side."},{"s":276.49,"e":279.67,"t":"The halfway point is just to the right of these buildings."},{"s":280.35,"e":282.15,"t":"Just cheer the kids on."},{"s":282.39,"e":285.53,"t":"And if anyone has given up running, that's fine."},{"s":286.33,"e":291.63,"t":"Okay, the teacher at our first aid post might need help sticking plasters on."},{"s":323.51,"e":328.63,"t":"This means heading up the footpath by the school, then keep going up."},{"s":328.75,"e":333.21,"t":"With the flag post on your left and the satellite dish on your right."},{"s":333.51,"e":337.21,"t":"And the filming spot is just there in front of the trees."},{"s":337.65,"e":341.71,"t":"Well I think that covers everything, but if you have any questions, please."}],"3":[{"s":59.26,"e":64.64,"t":"So we're here to talk over our first assignment on alternative building materials."},{"s":64.76,"e":70.14,"t":"Yeah, I think it will be really interesting to learn more about how plastic has been used."},{"s":70.38,"e":73.96,"t":"I found lots of information from the 1960s."},{"s":73.9,"e":80.06,"t":"So did you find out why the idea of plastic buildings wasn't popular with the public at that time?"},{"s":80.16,"e":83.5,"t":"It wasn't the materials' environmental credentials."},{"s":83.2,"e":87.8,"t":"The concept of plastic houses was just too futuristic."},{"s":88.22,"e":90.26,"t":"So you mean it was their appearance?"},{"s":91.54,"e":98.5,"t":"People liked their modern design, but the idea of that sort of building as a home just didn't appeal."},{"s":99.72,"e":107.0,"t":"I did some research on the kind of problems engineers had with the old plastics in the 1960s and 1970s."},{"s":106.7,"e":108.32,"t":"What did you learn?"},{"s":108.66,"e":115.54,"t":"Well, firstly, because plastic doesn't weigh very much, the buildings weren't very good in windy weather."},{"s":125.88,"e":131.18,"t":"And when rain got into these cracks, the plastic would deform and lose its strength."},{"s":132.48,"e":137.08,"t":"I wonder where we can find some more information about the situation nowadays."},{"s":137.74,"e":140.88,"t":"Maybe we could ask one of the PhD students."},{"s":140.94,"e":143.1,"t":"I expect they'll be too busy."},{"s":143.14,"e":144.78,"t":"Yeah, that's true."},{"s":145.24,"e":147.86,"t":"Well, we could always use the internet."},{"s":148.3,"e":153.84,"t":"Maybe we should research more academic sources like the journals we have in the library."},{"s":154.76,"e":159.98,"t":"Okay, that way we can reference everything properly at the end of the assignment."},{"s":160.64,"e":163.8,"t":"Have you read Peterson's article about plastic houses?"},{"s":163.74,"e":166.0,"t":"Yeah, it was really good."},{"s":166.18,"e":169.14,"t":"But it didn't have enough illustrations of the houses."},{"s":169.34,"e":170.66,"t":"That was a shame."},{"s":170.82,"e":174.02,"t":"They'd have been useful for us as examples in our presentation."},{"s":174.6,"e":176.76,"t":"I liked the way it was organised though."},{"s":176.74,"e":178.46,"t":"That was really clear."},{"s":234.97,"e":239.17,"t":"Okay, well shall we start comparing our findings then?"},{"s":238.87,"e":241.05,"t":"Sure, I'll make some notes."},{"s":253.83,"e":257.25,"t":"It was on show at a theme park in America for ten years."},{"s":257.69,"e":261.95,"t":"After that, they demolished it, but they had a hard time."},{"s":262.13,"e":264.17,"t":"It was really built to last."},{"s":264.25,"e":266.29,"t":"But they couldn't break the plastic up."},{"s":265.99,"e":270.27,"t":"Was that the one that had an ultrasonic dishwashing machine?"},{"s":270.17,"e":274.13,"t":"Yes, that would still be pretty revolutionary today."},{"s":274.81,"e":276.87,"t":"Did you read about The Wonder House?"},{"s":277.29,"e":282.67,"t":"It was designed in 1964 by an industrial designer called Alfred Noise."},{"s":282.67,"e":287.37,"t":"Oh, the one with the roof like a sort of tent or an umbrella."},{"s":288.35,"e":295.53,"t":"The roof was made of fibre glass and it curved down to the ground at each corner, in closing a big central space."},{"s":295.99,"e":299.01,"t":"And the sides were filled with glass or plastic."},{"s":299.35,"e":305.99,"t":"It was a really innovative idea for the time, but noise only made a small model and the design wasn't implemented."},{"s":308.01,"e":313.97,"t":"What about those spaceship houses they built between 1968 and 1978?"},{"s":314.31,"e":315.95,"t":"Like flying sources."},{"s":316.15,"e":317.91,"t":"They built over a hundred of them."},{"s":318.05,"e":320.29,"t":"I don't know if I'd want to live in one."},{"s":320.49,"e":324.69,"t":"The living area was quite limited, and they had really low ceilings."},{"s":324.39,"e":327.77,"t":"But they do look really futuristic, don't they?"},{"s":327.55,"e":331.17,"t":"With their white walls and circular shape, yes."},{"s":331.15,"e":337.83,"t":"But the plastic houses I like are the foam houses they built between 1979 and 1983."},{"s":338.23,"e":340.63,"t":"They've got really curvy shapes."},{"s":340.77,"e":344.65,"t":"They built them by spraying foam over a great big balloon."},{"s":345.09,"e":353.09,"t":"They were partly built to show what computers could do in the home, at things like controlling heat and light and so on."},{"s":353.25,"e":355.13,"t":"Quite new ideas at the time."},{"s":355.61,"e":359.79,"t":"And they were very well insulated as well, so they saved energy."},{"s":360.13,"e":362.65,"t":"People were just beginning to get into that."},{"s":362.83,"e":369.17,"t":"I read about a plastic exhibition hall that can all be packed away in a relatively small container."},{"s":369.65,"e":374.15,"t":"You just put it on a truck and take it to wherever you want it, then inflate it."},{"s":374.31,"e":378.59,"t":"You know, fill it up with air and there's room for hundreds of people."},{"s":378.29,"e":385.47,"t":"And when the exhibition or whatever's over, you just take it down again, and you can reuse it again and again."},{"s":385.57,"e":392.61,"t":"And there's a house in New Zealand that's built from household and industrial waste, like plastic boxes."},{"s":392.99,"e":398.65,"t":"They say it's a much better construction material than bricks, from the point of view of insulation."},{"s":398.75,"e":403.77,"t":"Yes, they're using that idea to build houses in other parts of the world, too."},{"s":411.33,"e":413.07,"t":"The end of Part 3."}],"4":[{"s":77.11,"e":81.07,"t":"Welcome back to this series of lectures on the development of photography."},{"s":81.77,"e":91.03,"t":"Last week, we looked at a type of photography called digerotype, the first commercially successful photographic process."},{"s":91.87,"e":98.31,"t":"Today, we're going to look at how this was gradually replaced by a technique called calotype."},{"s":99.03,"e":104.83,"t":"Degarotype was a major breakthrough but there were problems with it."},{"s":105.23,"e":112.17,"t":"In particular because the image was produced on a copper sheet it was expensive to create each photograph."},{"s":113.25,"e":121.49,"t":"As a result during the 1840s a man named William Talbot began looking for an alternative approach."},{"s":122.05,"e":125.71,"t":"Talbot eventually became an influential figure."},{"s":125.41,"e":129.77,"t":"But he always said he was not a professional photographer."},{"s":130.59,"e":133.29,"t":"In fact, he trained as an artist."},{"s":134.13,"e":136.55,"t":"His greatest interest was painting."},{"s":137.55,"e":141.81,"t":"And he only became involved with photography as a secondary interest."},{"s":143.49,"e":149.49,"t":"Talbot spent many years trying to solve the problems associated with Deguera-type photography."},{"s":150.29,"e":156.67,"t":"He tried a number of different approaches, and it took some time to find a success. alternative."},{"s":169.57,"e":176.27,"t":"Talbot's technique, which he called calotype photography, had other advantages as well."},{"s":177.25,"e":183.39,"t":"Maybe the most important, was that the pictures themselves weren't as sharp as the ones produced before."},{"s":183.09,"e":188.37,"t":"The sharpness had been a problem because it distorted everything."},{"s":188.79,"e":195.33,"t":"But this new calotype process produced images that were realistic compared to all earlier photographs."},{"s":197.96,"e":204.18,"t":"Calotype photography was invented in Britain, but it was also popular with French photographers."},{"s":205.2,"e":212.34,"t":"The 1850s were a time of rapid development in France, and photography was used to record these changes."},{"s":228.32,"e":236.02,"t":"To begin with, there were five members, and maybe the most important was a man called Gustav LeGrée."},{"s":236.68,"e":241.36,"t":"LaGrée became increasingly fascinated by the calotype process."},{"s":242.46,"e":250.3,"t":"Most of all, he wanted to produce different types of image, so began a series of experiments to see how this might be done."},{"s":251.54,"e":260.16,"t":"His greatest success was when he designed the first camera that was able to create enlargements, an important step forward."},{"s":261.3,"e":267.54,"t":"Another of LaGrace Innovations was his work on the size of the equipment necessary to take photographs."},{"s":268.22,"e":275.22,"t":"Originally it was very heavy and difficult to move about, but LaGrée made it lighter and smaller."},{"s":276.28,"e":285.56,"t":"This meant he could take photographs outdoors more easily rather than being limited to the studio, which had sometimes been the case until then."},{"s":285.72,"e":292.34,"t":"LaGrée produced numerous photographs during this period and was highly regarded among fellow photographers."},{"s":309.34,"e":312.92,"t":"The simple fact was that people liked photography."},{"s":313.6,"e":321.08,"t":"They thought it was reliable, especially compared to drawing, where the human hand might alter or exaggerate things."},{"s":335.0,"e":338.18,"t":"The camera doesn't lie, so people said."},{"s":339.38,"e":348.84,"t":"As a result, the calotype process was admired not only by photographers, but increasingly by the government and by mainstream society."},{"s":349.66,"e":357.1,"t":"However, debate still remained about whether photography could truly be called an art form like sculpture or drawing."},{"s":357.26,"e":365.48,"t":"Certainly, although the public liked it. in the opinion of critics, photography could not be compared to other established forms of art."},{"s":367.71,"e":372.69,"t":"So, in summary, what can we say about calotype photography during this period?"},{"s":373.83,"e":380.63,"t":"One thing to re-emphasise is that the 1850s were a period of great development in Britain and France."},{"s":393.97,"e":400.09,"t":"However, photographers didn't stop experimenting with new materials to improve the quality of their work."},{"s":400.97,"e":408.93,"t":"Most of all, they were searching for ways to make images more permanent because calotype photographs tended to fade over time."},{"s":409.67,"e":415.65,"t":"And in the end, they found that if the image was produced on glass, it lasted much longer."},{"s":415.35,"e":422.37,"t":"So, calotype photography was slowly replaced by other techniques which had greater law."}]},"4":{"1":[{"s":98.61,"e":101.87,"t":"Hello, Coxhead Motor Homes, Dave Sparrow speaking."},{"s":103.23,"e":106.31,"t":"I would like to inquire about renting an RV for a week."},{"s":106.55,"e":109.39,"t":"I think you call them motor motor homes in the UK."},{"s":110.89,"e":113.23,"t":"Well, we should be able to help you there."},{"s":113.57,"e":115.35,"t":"So what type were you thinking ."},{"s":115.89,"e":119.19,"t":"It's just for two of us. and my husband."},{"s":120.09,"e":124.43,"t":"Right, the best model for you would be the two birth end kitchen."},{"s":124.73,"e":130.09,"t":"That's the one with the sitting and sleeping area in the middle and the other facilities at the back."},{"s":130.27,"e":132.05,"t":"Yes, that sounds good."},{"s":132.27,"e":134.55,"t":"And what sort of price is that?"},{"s":134.79,"e":140.41,"t":"The cost starts at 545 pounds a week depending on when you wanted for."},{"s":140.57,"e":144.63,"t":"If it's high season, it goes up to 755 pounds."},{"s":144.33,"e":146.45,"t":"And is that all-inclusive?"},{"s":147.29,"e":149.77,"t":"There's what we call a damage deposit."},{"s":149.97,"e":153.51,"t":"That's fully refundable if the vehicle is returned in good condition."},{"s":153.83,"e":155.99,"t":"That depends on the driver's age."},{"s":155.89,"e":159.71,"t":"You do have to be at least 21 to drive one of these vehicles."},{"s":162.05,"e":167.45,"t":"Well, in that case, if you're driving the vehicle, the deposit would be £460."},{"s":167.15,"e":172.53,"t":"It goes down to 250 pounds for drivers of 26 and above."},{"s":172.95,"e":176.11,"t":"And do I have to pay more if my husband drives as well?"},{"s":176.31,"e":178.33,"t":"No, extra drivers are free."},{"s":179.39,"e":181.79,"t":"We have to pay a supplement for that in the States."},{"s":182.15,"e":184.55,"t":"So you've driven one of these before, have you?"},{"s":184.83,"e":187.09,"t":"Yes, but only in America."},{"s":187.57,"e":190.35,"t":"Oh, that reminds me about my driving license."},{"s":190.49,"e":192.25,"t":"I've got an international one."},{"s":194.29,"e":197.73,"t":"And I just have a few questions about the motorhomes if that's all right?"},{"s":198.91,"e":203.77,"t":"So first of all, can you tell me how old your vehicles are on average?"},{"s":203.99,"e":208.87,"t":"They're all less than 30 months, so you're getting a vehicle in peak condition."},{"s":209.31,"e":213.27,"t":"Okay, and I'd prefer an automatic gearbox if possible."},{"s":214.57,"e":218.13,"t":"I'm afraid not, they're all manual, will that be a problem?"},{"s":217.83,"e":220.31,"t":"Oh, I guess I'll be okay."},{"s":231.67,"e":234.73,"t":"Oh, well, that won't apply to us, but it's nice to know."},{"s":276.28,"e":279.44,"t":"And I suppose there are cooking facilities in the motor home?"},{"s":279.68,"e":281.96,"t":"Yes, there's everything you need for cooking."},{"s":283.5,"e":286.96,"t":"Yes, and you've got a built-in microwave too."},{"s":287.22,"e":289.26,"t":"And you said it sleeps too."},{"s":289.48,"e":291.94,"t":"So is that two singles or a double?"},{"s":292.42,"e":295.08,"t":"You can arrange the bed either way."},{"s":294.78,"e":296.66,"t":"And you've got a CD player?"},{"s":296.86,"e":300.82,"t":"And this year we've installed a television in every motor home as well."},{"s":301.9,"e":304.66,"t":"Well, that might be useful if we have a rainy day."},{"s":305.12,"e":307.22,"t":"Oh, and what about Satnav?"},{"s":307.46,"e":309.56,"t":"I don't suppose that's included, is it?"},{"s":310.42,"e":314.02,"t":"We've had that in all our mobile homes for a few years now."},{"s":314.06,"e":316.22,"t":"Our customers really appreciate it."},{"s":317.0,"e":319.82,"t":"Oh, and what about a rack for my bicycle?"},{"s":320.04,"e":321.54,"t":"I'd like to take it along."},{"s":321.54,"e":323.3,"t":"Yes, we can arrange for that."},{"s":323.76,"e":325.86,"t":"Now what happens about electricity?"},{"s":326.36,"e":332.36,"t":"I think we'll probably be staying at campsites most of the time, so presumably there'll be mains hook-up there."},{"s":354.02,"e":355.52,"t":"We'll be arriving by train."},{"s":356.18,"e":359.4,"t":"Well, if you want, we can pick you up from the station."},{"s":364.08,"e":370.38,"t":"That's spelled G-R-A-T-E-L-E-Y."},{"s":370.08,"e":374.12,"t":"There's no charge for that, just let us know when you'll be arriving."},{"s":374.88,"e":377.44,"t":"So would you like to go ahead and book a vehicle now?"},{"s":378.8,"e":380.51,"t":"So my name is Christie and..."}],"2":[{"s":50.84,"e":56.88,"t":"Today we're pleased to welcome Jan Beamish who's the director of the Citadel theater."},{"s":57.42,"e":61.36,"t":"So Jan what does the theater have in store for us in the next few months?"},{"s":62.34,"e":67.42,"t":"present we've got comedy shop which features five comedians doing sketches."},{"s":67.86,"e":73.38,"t":"It's very popular because some of the people watching the show have the chance to come and join in the sketches."},{"s":73.9,"e":75.62,"t":"It's had excellent reviews."},{"s":76.18,"e":79.28,"t":"Then after that there's a new play called Seekers."},{"s":79.74,"e":87.08,"t":"This is a very beautiful story about childhood featuring Abigail Garrick who's one of the country's top actors."},{"s":87.46,"e":90.92,"t":"But sadly there are no more tickets left for any of the performances."},{"s":92.34,"e":98.8,"t":"We're also putting on the hidden box, which is a delightful fantasy about a search for lost treasure."},{"s":99.12,"e":106.3,"t":"It goes down very well with youngsters, particularly preschool, and actually the whole family will enjoy it too."},{"s":106.88,"e":110.36,"t":"There are still quite a number of tickets left for afternoon performances."},{"s":111.7,"e":116.14,"t":"For one week only, we've been lucky enough to secure night shift."},{"s":116.44,"e":122.12,"t":"A fascinating new play, based on the diary kept by a factory owner in the 19th century in the 19th century."},{"s":136.72,"e":144.62,"t":"Next month, sees the start of a production called John Dory, a light-hearted show based on stories from the local area."},{"s":157.94,"e":161.32,"t":"And finally, I mustn't forget vital signs."},{"s":222.24,"e":227.28,"t":"And this summer the Citadel is once again supporting the Youth Arts Festival."},{"s":227.4,"e":228.98,"t":"Can you tell us a bit about that?"},{"s":256.78,"e":262.0,"t":"That's just a few months before the festival itself which will be in the first week of August."},{"s":262.62,"e":267.4,"t":"If anyone would like to put on a performance themselves, there's still time to apply."},{"s":268.0,"e":270.72,"t":"You can download the application form from our website."},{"s":271.44,"e":274.36,"t":"Make sure you complete all the relevant sections."},{"s":275.12,"e":278.0,"t":"You need to briefly describe what happens in the performance."},{"s":278.52,"e":282.98,"t":"If you want, you can also send a DVD or photos of the performance."},{"s":284.02,"e":288.32,"t":"You will be expected to provide your own costumes and music, by the way."},{"s":288.72,"e":294.48,"t":"There's also a competition for anyone who's interested in actually writing a short play."},{"s":305.98,"e":310.36,"t":"Last year's winning play was even shown on national TV afterwards."},{"s":311.54,"e":320.28,"t":"The highlight of the festival will be a production of the experimental play, Calcaman, acted and written entirely by young people."}],"3":[{"s":58.36,"e":63.6,"t":"Thank you for coming in to discuss the work you've done so far on your assignment on multinational companies."},{"s":64.24,"e":65.76,"t":"I've had a good look at it."},{"s":67.02,"e":71.74,"t":"I'm interested in your research on this chocolate and its brand image."},{"s":86.76,"e":93.28,"t":"Did you know that they used different amounts of caffeine and sugar to appeal to tastes in different countries, to."},{"s":92.98,"e":94.48,"t":"Oh I didn't."},{"s":95.06,"e":96.76,"t":"I'll look into that too."},{"s":102.14,"e":108.18,"t":"Well I got a bit lost when you talked about starting production in another country."},{"s":121.74,"e":126.8,"t":"Well, I mean, You could then link that to profits to finish off that section."},{"s":126.84,"e":128.58,"t":"Yes, that's down on my plan."},{"s":129.12,"e":136.0,"t":"Another thing that's grabbed my attention is the messages for young people in advertising by multinationals."},{"s":136.3,"e":138.08,"t":"You could follow up on that thought."},{"s":138.8,"e":140.52,"t":"Other moral issues come up."},{"s":140.26,"e":147.12,"t":"For example, the supermarket chain who offered free plastic bags in a market which is very environment-conscious."},{"s":152.48,"e":159.2,"t":"seen everywhere in town, but they'd forgotten that that market didn't want any more plastic polluting their environment."},{"s":159.52,"e":160.92,"t":"A big mistake."},{"s":161.52,"e":165.54,"t":"There seems to be a sort of arrogance on the part of some multinationals."},{"s":165.26,"e":166.6,"t":"In what way?"},{"s":166.38,"e":175.48,"t":"Well, it's okay if the multinational comes into your country, takes over a company, and introduces better working conditions or new machinery."},{"s":175.88,"e":181.32,"t":"But it's the way they often bring in their own management team who ride rough-shod over everyone."},{"s":182.48,"e":185.66,"t":"exactly go in for consultation at local level."},{"s":185.9,"e":187.56,"t":"That's an interesting observation."},{"s":188.3,"e":190.42,"t":"What do you have in mind for the last section?"},{"s":190.62,"e":192.6,"t":"I'd like to look at distribution."},{"s":193.12,"e":197.42,"t":"It can be key to the success or failure of so many businesses."},{"s":197.84,"e":204.02,"t":"Of course, there's the whole idea of managing time and what happens when customers don't get their goods on time."},{"s":204.38,"e":209.76,"t":"But I'd like to read up on the effects of managing all distribution from just one office."},{"s":209.46,"e":216.1,"t":"Because if a company isn't used to that and it's suddenly introduced, it can be chaos."},{"s":216.66,"e":222.08,"t":"I looked at the issue of stock control in last term's paper, so I'd rather not revisit that."},{"s":263.29,"e":266.85,"t":"Now you need to finish off with a company case study."},{"s":266.55,"e":270.21,"t":"And I see you've been looking into some possibilities."},{"s":270.51,"e":272.63,"t":"What did you find out about Drummond's?"},{"s":272.51,"e":277.63,"t":"At first I thought they'd be good to illustrate the importance of getting the workforce right."},{"s":278.07,"e":280.55,"t":"But I'm not sure I'd have enough information."},{"s":289.83,"e":291.33,"t":"That's what Drummond's did."},{"s":291.03,"e":293.51,"t":"Yes, that could be good."},{"s":294.11,"e":295.59,"t":"There's also multi-plan."},{"s":305.89,"e":311.05,"t":"So no matter where they'd expanded their business to abroad, they'd have faced the same problems."},{"s":311.55,"e":313.35,"t":"What about elbeats?"},{"s":324.25,"e":329.09,"t":"Yes, they would be a good choice because it would allow you to present data effectively."},{"s":329.87,"e":331.87,"t":"Babas would be good for that too."},{"s":331.97,"e":336.79,"t":"All the figures relating to their staffing levels before and after going global are available."},{"s":336.75,"e":339.23,"t":"Oh, and they're huge, aren't they?"},{"s":348.57,"e":356.07,"t":"So, just check through to see which one would give you scope to develop a good case study with a clear focus."}],"4":[{"s":75.36,"e":79.42,"t":"Today I want to talk to you about something called a soundscape."},{"s":80.26,"e":82.94,"t":"We all know what a landscape is."},{"s":83.34,"e":86.34,"t":"That is the view that you can see from any particular point."},{"s":87.02,"e":95.58,"t":"As the name implies, a soundscape comprises all the sounds you can hear at a given time in a particular environment."},{"s":107.06,"e":114.78,"t":"One important aspect of the soundscape is that it is not random abstract noise."},{"s":115.16,"e":123.2,"t":"Nor is it simply mindless background sounds such as the recorded music you hear so often in public places like elevators."},{"s":123.76,"e":130.68,"t":"No, the sounds in a soundscape generally have meaning and can be understood and decoded."},{"s":131.66,"e":136.78,"t":"The sounds of which a soundscape is composed can be divided into three types."},{"s":150.14,"e":152.18,"t":"Some people love that sound."},{"s":152.78,"e":161.68,"t":"Then, the second type of soundscape sound is termed geophony, and that is sound created by non-biological forces."},{"s":199.1,"e":203.22,"t":"He came to several interesting conclusions about the sounds he recorded."},{"s":216.78,"e":225.24,"t":"Furthermore, Krause concluded that the sounds of various organisms in an environment are harmonious in two ways."},{"s":225.82,"e":231.28,"t":"Firstly, they fit together in terms of loudness, and thus they don't drown each other out."},{"s":231.78,"e":237.22,"t":"And secondly, the frequency of each sound is also harmonious with the other sounds."},{"s":265.14,"e":271.22,"t":"Change in the soundscape may also be a first warning sign of pollution of many kinds."},{"s":287.46,"e":297.9,"t":"Soundscape ecologists are using ever more sophisticated equipment to study the sounds of nature, including the state-of-the-art acoustic sound recorders."},{"s":298.58,"e":305.6,"t":"The data from these are used to create three-dimensional maps of acoustic features plotted across a landscape."},{"s":318.34,"e":326.7,"t":"Now when I give talks, the most common question that I get asked is, what's the loudest creature in the animal world?"},{"s":327.06,"e":334.24,"t":"The answer is probably debatable, but it's not a bellowing elephant."},{"s":333.94,"e":338.54,"t":"To the best of my knowledge, it's something found in the ocean."},{"s":351.26,"e":354.46,"t":"And that's even more than the noise a rock band makes."},{"s":355.4,"e":367.26,"t":"Now, if you have a rock..."}]},"5":{"1":[{"s":102.95,"e":106.15,"t":"Nature Park Services, how am I help you today?"},{"s":106.11,"e":110.31,"t":"Hello, I'm calling to make a campsite reservation."},{"s":110.47,"e":115.13,"t":"Great, let me just pull up the reservation form and we can get started."},{"s":115.67,"e":118.35,"t":"Okay, first, could I get your name?"},{"s":118.41,"e":120.45,"t":"Sure, it's Sandra Kemp."},{"s":120.15,"e":121.87,"t":"All right, Ms."},{"s":122.49,"e":127.53,"t":"I can make reservations for the Northern, Central, and Southern California parks."},{"s":127.89,"e":129.81,"t":"Which region will you be traveling to?"},{"s":129.83,"e":133.31,"t":"Is Mount Laguna in the Central or Southern region?"},{"s":133.71,"e":135.05,"t":"Is that where you're going?"},{"s":137.25,"e":138.93,"t":"Do you know which campground?"},{"s":139.05,"e":142.45,"t":"Actually, I was hoping you could help me with that."},{"s":142.91,"e":147.71,"t":"I've read a lot about two different campgrounds, sunrise and mountain."},{"s":150.15,"e":153.51,"t":"campground has many hiking trails close by."},{"s":153.99,"e":160.25,"t":"But then again, Sunrise Campground is next to the lake and my husband loves to fish."},{"s":161.67,"e":163.71,"t":"They're both really beautiful spots."},{"s":164.15,"e":166.09,"t":"I guess it depends on when you're going."},{"s":166.91,"e":169.21,"t":"Well, we're going in April."},{"s":169.55,"e":175.21,"t":"The thing is, fishing at Sunrise Campground is only allowed from June to September."},{"s":175.53,"e":177.25,"t":"So I suggest mountain."},{"s":176.95,"e":179.79,"t":"Okay, then, that makes it easy."},{"s":180.29,"e":185.53,"t":"So we've selected the campground, so now we need to think about which sort of site."},{"s":185.83,"e":187.47,"t":"There are different options."},{"s":187.95,"e":193.17,"t":"You can stay at a cabin, a tent, or a recreational vehicle campsite."},{"s":193.23,"e":196.73,"t":"Which type of site offers the most peace and quiet?"},{"s":196.81,"e":199.09,"t":"A tent site would be your best bet."},{"s":199.05,"e":200.41,"t":"Sounds good to me."},{"s":201.43,"e":208.67,"t":"So, if you've read about the park, you probably know that some vehicles aren't suitable for the park roads."},{"s":208.91,"e":211.19,"t":"Cars tend to get stuck when it rains."},{"s":211.85,"e":214.37,"t":"If you have a truck, you won't have any trouble."},{"s":215.83,"e":218.47,"t":"We'll be driving that instead of our car."},{"s":218.85,"e":222.89,"t":"I hope we don't get any rain, but I'd rather be safe than sorry."},{"s":224.17,"e":226.59,"t":"I'll just need to get your license plate number."},{"s":232.09,"e":233.59,"t":"And what about your trip dates?"},{"s":233.71,"e":236.03,"t":"We'd like to stay for three days."},{"s":236.25,"e":238.35,"t":"Does that mean you'll be staying two nights?"},{"s":239.29,"e":243.49,"t":"We'll be arriving on April 10th and leaving on the 12th."},{"s":279.46,"e":287.58,"t":"Now, the park is home to some black bears. so you'll need to rent a bare-proof food container. to lock your food inside for hikes."},{"s":288.08,"e":289.56,"t":"It's really just a precaution."},{"s":290.0,"e":293.7,"t":"We have small, medium, and large food containers for campers."},{"s":293.66,"e":297.7,"t":"Oh, I'm familiar with food containers, but they can be heavy."},{"s":297.76,"e":302.54,"t":"Well, the large one is, but if you get the small size, it's not so heavy."},{"s":302.52,"e":303.92,"t":"Well, let's do that."},{"s":304.04,"e":305.58,"t":"I really want something lightweight."},{"s":306.3,"e":311.04,"t":"Would you be interested in signing up for a guided nature walk? on the second day of your trip?"},{"s":310.92,"e":312.34,"t":"Oh, what kind of walk?"},{"s":312.1,"e":316.8,"t":"Well, at 7 a.m. there are three different ones near your campground."},{"s":317.2,"e":321.4,"t":"There's the flower walk, the bird-watching walk, and the waterfall walk."},{"s":322.52,"e":326.4,"t":"I love gardening, so the flower walk sounds interesting."},{"s":326.8,"e":332.64,"t":"My son might be more into the waterfall one, but I can't imagine him getting up in time."},{"s":333.02,"e":339.02,"t":"Maybe I could go alone. could you sign me up. sure. a few more more things."},{"s":339.4,"e":342.24,"t":"Visitors must purchase park passes as well."},{"s":350.46,"e":352.5,"t":"Let's go ahead and get that."},{"s":352.56,"e":354.98,"t":"I'm sure we'll visit more parks soon."},{"s":355.22,"e":356.62,"t":"It's a really good bargain."},{"s":357.06,"e":361.86,"t":"Plus, we donate $5 of the pass fee to one of our three park programs."},{"s":362.08,"e":363.58,"t":"You get to choose which one."},{"s":365.66,"e":370.34,"t":"Well, we run a youth program for local kids to attend a nature camp in the summer."},{"s":370.84,"e":373.4,"t":"The other two options are conservation projects."},{"s":373.78,"e":376.92,"t":"There's a wildlife program and a tree planting program."},{"s":377.0,"e":379.24,"t":"Wow, they all sound worthwhile."},{"s":380.96,"e":385.44,"t":"Um, it's important for children to appreciate the outdoors."},{"s":385.78,"e":387.58,"t":"Let's go with the youth program."},{"s":388.88,"e":392.1,"t":"We just need to review the fee and payment information information."}],"2":[{"s":54.62,"e":56.4,"t":"Good morning all of you."},{"s":56.74,"e":59.96,"t":"I do apologize for being a little late starting our meeting."},{"s":75.0,"e":79.64,"t":"Now this is the first day of work at the Ocean Edge Hotel for all of you."},{"s":80.18,"e":82.74,"t":"Let me say something that might surprise you."},{"s":82.56,"e":88.24,"t":"You've all got a qualification in hospitality, and some of you have got very high grades."},{"s":87.94,"e":98.4,"t":"But to me, what counts most is that you enjoy the contact with guests and really want to make a career in the hospitality industry."},{"s":98.62,"e":103.4,"t":"You'll be getting some very valuable experience here, so make the most of it."},{"s":103.7,"e":107.7,"t":"A few words about the history of the Ocean Edge Hotel."},{"s":108.2,"e":112.58,"t":"There have been buildings on this site for about 250 years."},{"s":112.98,"e":118.22,"t":"We know that in the 18th century there was a bakery here, when the town was very nice."},{"s":117.94,"e":125.4,"t":"The building was destroyed by fire in the early 19th century and houses were constructed on the site."},{"s":125.68,"e":132.14,"t":"These in their turn were demolished in the middle of the 20th century and replaced by the hotel."},{"s":133.0,"e":137.08,"t":"I think it's fair to say that this is a popular place to work."},{"s":137.72,"e":143.36,"t":"We're always getting job applications from local people, even when we haven't any vacancies."},{"s":143.06,"e":152.08,"t":"And whereas in many hotels, staff tend to stay for a year or even less, here five is pretty standard."},{"s":152.4,"e":156.66,"t":"And in fact, several of our staff have been here for 10 years or more."},{"s":156.94,"e":161.26,"t":"You're the first people we've appointed in the last three years."},{"s":161.64,"e":167.5,"t":"And we only needed to do that because we're currently constructing 25 new bedrooms."},{"s":167.92,"e":175.38,"t":"Depending on their location, hotels usually have mostly business guests or mostly tourists."},{"s":175.84,"e":180.86,"t":"We attract a large number of tourists who come to spend a few days beside the ocean."},{"s":181.24,"e":187.86,"t":"We also have quite a lot of people who are here on business and perhaps stay for one or two nights."},{"s":188.66,"e":194.16,"t":"What we've noticed recently though is that we're getting more and more regulars."},{"s":193.86,"e":200.32,"t":"People staying here for four nights every week, because they have jobs in this locality."},{"s":200.66,"e":203.16,"t":"But live somewhere else in the country."},{"s":203.34,"e":205.18,"t":"So they go home for the weekend."},{"s":240.1,"e":250.97,"t":"Now let me give you an idea of the layout of the hotel."},{"s":261.11,"e":267.73,"t":"Obviously, when they arrive, the first place they find themselves in is the reception area, where we're sitting."},{"s":268.25,"e":273.61,"t":"The desk is over on the right of the entrance, and the office is immediately behind it."},{"s":273.77,"e":285.13,"t":"There's a connecting door from the desk itself and another entrance from the corridor residents hire the function room for parties and other events."},{"s":285.69,"e":291.05,"t":"This is right at the front of the hotel, on the left of the reception area, opposite the desk."},{"s":291.63,"e":296.33,"t":"This room is booked several evenings a week, and most weekends."},{"s":296.47,"e":298.47,"t":"It's a major source of income."},{"s":299.39,"e":306.95,"t":"Companies are very important customers for us, and a large number of local firms hold conferences here."},{"s":307.39,"e":316.09,"t":"To reach the main conference room, you go past the fountain as far as you can and the doors directly in front of you."},{"s":316.77,"e":322.93,"t":"The meeting room is often hired by companies and other local organizations for small gatherings."},{"s":332.13,"e":342.25,"t":"Our restaurant is open to the public, as well as to hotel residence. and I'm pleased to say it has a very good reputation locally."},{"s":342.65,"e":350.45,"t":"You turn left just before the fountain as though you're heading for the guest's rooms and it's the large room on your right."},{"s":351.13,"e":353.79,"t":"Next, I should mention that there..."}],"3":[{"s":57.16,"e":66.24,"t":"Now I've looked through your preliminary outline and notes for the presentation. on the art of the IFA region in Africa."},{"s":66.68,"e":68.3,"t":"That's in Nigeria, right?"},{"s":68.2,"e":74.44,"t":"Yes, I'm concentrating on IFA sculptures from the 12th to the 15th century."},{"s":74.72,"e":77.2,"t":"How did you get interested in that?"},{"s":77.7,"e":82.72,"t":"I know there have been some recent articles in the journals about African sculpture."},{"s":91.4,"e":95.74,"t":"I just happened to be there and I saw these works and thought they were fantastic."},{"s":96.68,"e":100.16,"t":"And I even went to Nigeria last summer to see more of them."},{"s":100.54,"e":110.02,"t":"I've seen the photos for your presentation and I must say the sculptures are gorgeous portrayals of what appear to be kings and queens."},{"s":110.16,"e":114.7,"t":"Yes, I decided to concentrate on those as they're the most typical."},{"s":115.14,"e":122.36,"t":"They're interesting because they're so naturalistic. unlike the abstract figures we often associate with African art."},{"s":133.3,"e":137.72,"t":"So what was the city of IFA like when these works were made?"},{"s":137.9,"e":139.94,"t":"It's on the Niger River, isn't it?"},{"s":140.96,"e":145.68,"t":"The boat traffics, what made it a centre of commerce then, as it still is today."},{"s":147.8,"e":149.38,"t":"with a big university."},{"s":149.54,"e":152.94,"t":"Speaking of modern day, Ephae, tell me about your trip."},{"s":153.6,"e":157.5,"t":"I was incredibly lucky to be able to get enough money to go."},{"s":157.7,"e":161.38,"t":"My parents encouraged me, but they couldn't afford to send me."},{"s":161.74,"e":165.84,"t":"I applied for a grant from the Arts Council, and in the end I got it."},{"s":174.84,"e":176.32,"t":"And the highlight of the trip?"},{"s":187.36,"e":189.42,"t":"He had been working at the site."},{"s":245.48,"e":250.7,"t":"Well, let's see what you might do to improve what you're planning for your presentation."},{"s":251.1,"e":258.08,"t":"About the sculptures themselves, I think I need to add as much as possible about the details of the way they were made."},{"s":258.52,"e":265.08,"t":"Of course, I can't add anything about the artists who made them, because nobody really knows anything about them."},{"s":264.78,"e":266.78,"t":"All good points."},{"s":267.2,"e":274.52,"t":"And you've certainly said enough about what the sculptures depict, what the subjects are, that's well covered."},{"s":274.68,"e":280.1,"t":"But I'd make some bigger photos of them, so you can clearly see the fine detail."},{"s":281.34,"e":286.4,"t":"And I would limit my personal reactions to these works of art if I were you."},{"s":286.6,"e":288.94,"t":"I know you think they're fantastic."},{"s":290.3,"e":292.22,"t":"I'll contain my enthusiasm."},{"s":297.88,"e":304.2,"t":"I'd like to go into more depth about the history of that whole area, you know, in the countries around Nigeria."},{"s":304.28,"e":312.96,"t":"That would make the presentation stronger, but I think you've covered the situation regarding the rulers of the country quite well."},{"s":313.32,"e":320.4,"t":"And you've got plenty already about what the IFA people were doing then and the way their society was structured."},{"s":320.1,"e":327.18,"t":"And in fact, I think you could cut out the bit about modern Nigerian history because it's not relevant."},{"s":327.24,"e":329.18,"t":"I agree, that doesn't fit."},{"s":329.86,"e":337.78,"t":"But perhaps I should concentrate more on the religious beliefs, since all these sculptures do seem to have some kind of religious association."},{"s":338.66,"e":340.38,"t":"I can lend you a book on that."},{"s":341.22,"e":350.16,"t":"Now, probably the part the class will find most interesting is the report of your trip to Nigeria and the research you did there."},{"s":350.1,"e":354.44,"t":"So I gather you managed to use the University Library in IFA."},{"s":354.54,"e":359.92,"t":"Yes, as soon as I'd explained why I wanted the information, that was no problem."},{"s":360.3,"e":362.02,"t":"They couldn't have been more helpful."},{"s":362.64,"e":369.34,"t":"There were some interesting accounts of how the first sculptures were found and what happened to them, which I want to include."},{"s":369.9,"e":378.32,"t":"What struck me when I saw the sculptures in Nigeria is the extent to which 20th century European artists were influenced by them."},{"s":380.1,"e":381.74,"t":"my presentation I think."},{"s":383.02,"e":386.52,"t":"What about the sources of the materials they used?"},{"s":386.72,"e":388.46,"t":"You don't mention that anywhere."},{"s":388.78,"e":391.42,"t":"I didn't manage to find out much about that."},{"s":392.06,"e":396.02,"t":"I want to cover the theories about who the original sculptors were though."},{"s":395.92,"e":400.22,"t":"Yes, the idea that a lot of them may have been made by the same person."},{"s":400.32,"e":401.64,"t":"That's very interesting."},{"s":402.84,"e":405.22,"t":"Right, well, thanks for all the advice."},{"s":405.64,"e":407.14,"t":"Now I think I need to work."}],"4":[{"s":74.67,"e":80.57,"t":"Today we're looking at urban migration, the movement of people migrating from outside cities, inter-sities."},{"s":82.47,"e":84.93,"t":"conclusion that a rural lifestyle is greener."},{"s":85.51,"e":88.11,"t":"However, recent studies have suggested otherwise."},{"s":106.03,"e":110.69,"t":"Anyway, let's imagine that most people decide to migrate to the city."},{"s":111.35,"e":113.15,"t":"What kind of impact would that have."},{"s":114.05,"e":122.69,"t":"For a start, this movement of people from the countryside should lift the pressure of intensive agriculture from the land, allowing forests to regenerate."},{"s":123.89,"e":131.47,"t":"Another point in favour of urban migration is that it can be far more energy efficient if services are concentrated in the city for example."},{"s":131.95,"e":135.35,"t":"This is true for electricity and as you can imagine water."},{"s":136.61,"e":144.59,"t":"Then, once you remember that rural communities are often very spread out, you can see yet another green reason to live in the city."},{"s":155.29,"e":157.59,"t":"The journeys tend to be shorter too."},{"s":158.41,"e":165.49,"t":"Yet another point in favour of urban migration is the kind of recycling schemes that can only take place where the population is concentrated."},{"s":166.23,"e":173.59,"t":"Take for instance, Seattle in the USA, where methane gas is being put to good use and as generating energy for the city."},{"s":174.27,"e":179.07,"t":"It's produced from the city's rubbish, which could not be collected so efficiently from rural areas."},{"s":180.57,"e":184.79,"t":"Now another factor that threatens the environment is the growing world population."},{"s":185.39,"e":192.63,"t":"It's estimated that 75 million babies are now born every year, and in some countries the birth rate shows no signs of slowing down."},{"s":193.13,"e":195.55,"t":"Urban migration may provide an answer here."},{"s":196.31,"e":204.03,"t":"Now in cities, one of the reasons that women tend to have fewer children is that they get married and start their families later."},{"s":204.57,"e":210.37,"t":"And the reason for this is that it's far easier to find a job and once you have one, to get a promotion."},{"s":211.01,"e":213.65,"t":"So yes, the focus isn't on bearing children."},{"s":218.54,"e":223.58,"t":"Well, it would be foolish to pretend that there are no downsides to urban living when clearly there are."},{"s":231.98,"e":236.7,"t":"Rather than give up their traditions, people actually work hard to maintain them."},{"s":245.46,"e":251.02,"t":"There won't be many of us here today who can say we haven't been directly or indirectly affected by it."},{"s":251.84,"e":253.88,"t":"There's another issue that we have to deal with."},{"s":254.28,"e":261.74,"t":"So many cities, including our own, now suffer from high levels of pollution so that the air we breathe is far from pure."},{"s":262.64,"e":268.98,"t":"And another factor against that urban is greener idea is that urbanisation often drives a country's economy."},{"s":269.36,"e":274.18,"t":"Put simply, when there is greater wealth in society, more energy is consumed."},{"s":287.26,"e":292.34,"t":"This is a problem that is not about to go away, although there There are some solutions that could be considered."},{"s":292.74,"e":294.06,"t":"Let's have a look at some of those."}]},"6":{"1":[{"s":41.02,"e":46.02,"t":"You will see that there is an example which has been done for you."},{"s":57.46,"e":63.02,"t":"I was wondering if you could spare a few minutes to do a questionnaire on your residency here in the North."},{"s":66.7,"e":70.06,"t":"First of all, may I get some information about yourself?"},{"s":70.96,"e":73.84,"t":"May I know your name and age?"},{"s":73.88,"e":77.66,"t":"My name is Lee and I'm 19 years old now."},{"s":77.36,"e":84.68,"t":"Lee says that he is 19 years old now, so 19 has been written in the space."},{"s":84.96,"e":86.48,"t":"Now we shall begin."},{"s":104.25,"e":109.83,"t":"I was wondering if you could spare a few minutes to do a questionnaire on your residency here in the north."},{"s":113.49,"e":116.73,"t":"First of all, may I get some information about yourself?"},{"s":118.03,"e":120.25,"t":"May I know your name and age?"},{"s":120.55,"e":124.11,"t":"My name is Lee, and I'm 19 years old now."},{"s":124.81,"e":127.01,"t":"And could I ask what your job is? ."},{"s":126.71,"e":128.47,"t":"Are you a student?"},{"s":128.97,"e":133.57,"t":"Actually, I'm going to continue my study in business management next month."},{"s":133.89,"e":136.83,"t":"But at the moment, I'm a salesman by profession."},{"s":137.97,"e":140.87,"t":"And how long have you been living here in the North?"},{"s":149.79,"e":154.51,"t":"Now I am 19, so I have spent about nine years living here, till now."},{"s":154.21,"e":158.25,"t":"Great, which part of the northern area do you live in?"},{"s":158.21,"e":160.01,"t":"I live in Spring Park."},{"s":162.69,"e":164.67,"t":"So, what about your accommodation?"},{"s":164.97,"e":168.69,"t":"Do you live in a house or a flat or something similar?"},{"s":179.17,"e":180.85,"t":"And, one more question. ."},{"s":180.55,"e":184.87,"t":"What means of transport will you take when you need to go somewhere?"},{"s":184.97,"e":190.69,"t":"Um, if it's not too far away, I'd prefer to go on foot or by bicycle."},{"s":190.71,"e":195.45,"t":"If there is a long way to go, I take the train or sometimes a cab."},{"s":195.75,"e":202.61,"t":"I rarely take buses, because I think the most important things to keep in mind are time and comfort."},{"s":241.8,"e":244.98,"t":"Now, let's go to the second part of my questionnaire."},{"s":245.2,"e":248.4,"t":"I'd like you to tell me, how often do you dine out?"},{"s":248.34,"e":251.9,"t":"Is it once a week or several times a year?"},{"s":252.0,"e":255.7,"t":"I'm afraid neither of those options agree with me."},{"s":255.88,"e":259.88,"t":"I don't often go out for dinner. once a month."},{"s":260.04,"e":262.58,"t":"Every week just seems too often for me."},{"s":262.52,"e":266.32,"t":"Okay, then where do you usually go for recreation?"},{"s":266.86,"e":269.92,"t":"I often go to places that other people go to."},{"s":270.28,"e":272.42,"t":"I sometimes go clubbing after work."},{"s":272.66,"e":275.18,"t":"You know there are some fantastic clubs nearby."},{"s":275.42,"e":280.48,"t":"And if you do not have to work during the day, will you go for a show or something?"},{"s":280.76,"e":288.2,"t":"You know, there is a newly built theatre that opened last month in Spring Park, but I rarely go there, because it's too expensive."},{"s":288.6,"e":292.32,"t":"I prefer to go to the cinema to see some of the latest movies."},{"s":292.5,"e":296.96,"t":"Do you like doing sports and what is your main form of exercise?"},{"s":297.64,"e":304.5,"t":"I like swimming and I go to the gym occasionally, but I spend most of my spare time sailing."},{"s":304.82,"e":307.06,"t":"All right, last question."},{"s":307.22,"e":309.52,"t":"Have you taken any part-time courses?"},{"s":310.3,"e":313.04,"t":"Yes, because I'm really keen on cartoons."},{"s":313.46,"e":317.86,"t":"I'm doing a Japanese course during the weekends, but I'm still a beginner still a beginner."},{"s":318.72,"e":320.82,"t":"What a special language!"},{"s":320.98,"e":324.22,"t":"Most people I know would like to learn Spanish or Latin."},{"s":325.86,"e":328.16,"t":"Well, thank you very much for your time."}],"2":[{"s":6.32,"e":9.04,"t":"Welcome to our holiday special."},{"s":9.06,"e":15.24,"t":"Today I'll be talking about a new cycle route in this area called the Elmsden Way."},{"s":15.5,"e":19.84,"t":"It's well signposted so you can see exactly where to go."},{"s":20.02,"e":23.24,"t":"And it's an easy route with no steep hills."},{"s":23.52,"e":32.04,"t":"It's 35 kilometers long from Elmsden to Langton and consists partly of cycle paths. and partly roads."},{"s":32.68,"e":37.26,"t":"Let me outline the route briefly, starting at Elmsden Railway Station."},{"s":37.82,"e":43.58,"t":"The first part is a cycle path running eastwards, roughly parallel to the rail track."},{"s":43.82,"e":50.14,"t":"Almost immediately, the railway curves away and goes around the southern side of a little lake."},{"s":50.44,"e":54.08,"t":"But the cycle path takes the northern route around the lake."},{"s":53.78,"e":57.82,"t":"Keep your eyes open for the swans that nest there."},{"s":58.18,"e":65.68,"t":"The path then joins the road and the next landmark is a group of massive rocks which tower over the countryside."},{"s":66.14,"e":71.62,"t":"You will see them to the east of the road just before the road goes under the railway."},{"s":72.1,"e":73.8,"t":"They are very impressive."},{"s":74.28,"e":80.82,"t":"Soon, you'll come to a fork in the road where you're going to leave the road and head off toward the river."},{"s":80.52,"e":89.08,"t":"But if you want to make a detour to Colleen Nature Reserve, go straight on instead of leaving the road here."},{"s":94.08,"e":97.06,"t":"The cycle path follows the river southwards."},{"s":97.16,"e":103.66,"t":"After a bit, you'll see the Ashington China Factory, which closed in 1962."},{"s":103.36,"e":113.16,"t":"When you get there, there's a bridge over the river and you carry on with Langton Forest to the south and farmland to the north."},{"s":113.5,"e":117.98,"t":"The route ends at Langton Village where you'll find a railway station."},{"s":150.28,"e":152.82,"t":"So be careful to avoid accidents."},{"s":153.42,"e":158.86,"t":"The path is well constructed, so it's not affected by wet or muddy conditions."},{"s":169.9,"e":173.28,"t":"Now, a bit more about some of the places you'll see."},{"s":173.54,"e":182.06,"t":"The starting point, Elmsden Station, was quite busy in the early 20th century with services to several major cities."},{"s":182.38,"e":185.32,"t":"But it was closed in the 1950s."},{"s":185.68,"e":195.22,"t":"And actually, a small company was set up to turn it into a sort of railway museum. maintaining it in the style of the 1950s."},{"s":195.78,"e":200.9,"t":"And the station was ready for trains to start using it again earlier this year."},{"s":201.42,"e":204.82,"t":"It's only used by a few local trains though."},{"s":205.06,"e":213.28,"t":"There's a visitor's center at the station which has a small exhibition about the history of railway transport all over the world."},{"s":213.44,"e":217.98,"t":"And a facility for hiring bikes if you don't have one of your own."},{"s":217.68,"e":223.98,"t":"There's also a small shop just across the road from the station that sells refreshments."},{"s":234.76,"e":236.42,"t":"There's no need to book."},{"s":236.7,"e":239.76,"t":"There's plenty of room and no extra charge."},{"s":239.96,"e":247.8,"t":"However, the service is very limited. and the trains between these two places don't run on weekday."},{"s":248.2,"e":253.56,"t":"If you want to see the River Elm, there's a footpath from Elmsden Station."},{"s":254.08,"e":257.5,"t":"And you can safely leave your bike in the car park there."},{"s":257.98,"e":260.42,"t":"Leave yourself plenty of time though."},{"s":260.54,"e":264.5,"t":"Going down is easy, but the climb up is very steep."},{"s":264.98,"e":268.66,"t":"So the walk back up to the top can take quite a while."},{"s":269.12,"e":270.86,"t":"But it's worth the effort."},{"s":270.56,"e":278.36,"t":"The scenery is wonderful and the footpath runs right next to the river down to a waterfall."},{"s":279.36,"e":285.66,"t":"Finally, if you'd like to do some more cycling in the area, there are lots of other cycle paths."},{"s":286.1,"e":294.32,"t":"We'll be talking on the radio about them and you'll be able to get full details in the Saturday edition of the local paper."},{"s":294.02,"e":303.66,"t":"The National Cycle Network also has some details on their website, although I have to say they don't have many local ones yet."},{"s":303.9,"e":305.34,"t":"But that may change."},{"s":305.86,"e":308.82,"t":"So we'll be telling you more about..."}],"3":[{"s":66.78,"e":69.04,"t":"Did you have a good time in Turkey?"},{"s":70.38,"e":72.12,"t":"I had a great time."},{"s":84.94,"e":92.88,"t":"Before I did my trip to Egypt, I was often irritated at not being able to picture exactly what the lecturers meant."},{"s":92.58,"e":96.04,"t":"They were always so excited about everything."},{"s":96.58,"e":101.8,"t":"Yeah, we did a lot of practical stuff on the excavation, which I really needed."},{"s":102.18,"e":103.94,"t":"Was it harder than you expected?"},{"s":105.68,"e":108.88,"t":"I learned a lot more about the rules of archaeology."},{"s":109.14,"e":114.92,"t":"I was really taken aback by how precise you have to be with your data collection and recording."},{"s":115.1,"e":118.74,"t":"I took loads of photographs and they proved very useful."},{"s":122.58,"e":123.9,"t":"good with the camera."},{"s":126.44,"e":129.54,"t":"I had no idea it would take so much time."},{"s":129.72,"e":133.46,"t":"Did you find anything particularly interesting when you were digging?"},{"s":133.34,"e":135.06,"t":"I did, actually."},{"s":135.14,"e":137.98,"t":"I had to dig a trench in part of the site."},{"s":149.34,"e":154.44,"t":"But our team leader said that they weren't, they were lead weights for weaving."},{"s":155.88,"e":160.94,"t":"I didn't find anything myself, but quite a few of the other students did."},{"s":161.2,"e":167.3,"t":"What I enjoyed was trying to identify what crops the people who had once lived in the area had grown."},{"s":167.78,"e":171.04,"t":"They seemed to have had a much better diet than I expected."},{"s":171.38,"e":175.98,"t":"Fish and wheat, as well as oats, honey and fruit, lots of different things."},{"s":175.68,"e":178.28,"t":"Yes, it's amazing, isn't it?"},{"s":188.92,"e":191.2,"t":"Probably due to less carbohydrates."},{"s":191.64,"e":193.9,"t":"How were the people you had to work with?"},{"s":193.6,"e":195.46,"t":"My team was great."},{"s":195.68,"e":199.62,"t":"They were made up of people my age from all over the world."},{"s":199.62,"e":204.4,"t":"It was good to work with them. lots of fun, and they taught me a lot."},{"s":205.68,"e":210.8,"t":"all, though, getting up at dawn every day and being out until late afternoon."},{"s":210.96,"e":212.78,"t":"Oh, that's true enough."},{"s":212.78,"e":218.54,"t":"We were all exhausted, and I'd like to have an international team next time."},{"s":218.72,"e":221.92,"t":"Mine was mainly made up of English and Americans."},{"s":222.24,"e":228.06,"t":"I enjoyed the field school, but everyone was much more experienced and older than I was."},{"s":228.32,"e":230.02,"t":"It was a bit scary."},{"s":242.82,"e":248.54,"t":"You know there's going to be a question about the excavation projects in our test next week."},{"s":248.86,"e":251.06,"t":"Should we just run through it for practice?"},{"s":252.6,"e":257.0,"t":"Our team leader was very strict about following the right procedure."},{"s":257.42,"e":263.04,"t":"He used to say, never excavate anything if you're not sure it's worth excavating."},{"s":276.9,"e":282.36,"t":"And you need to make sure you can remember what the site looks like before you begin digging."},{"s":282.66,"e":287.58,"t":"I think photos are probably best for that, rather than drawings at this stage."},{"s":297.4,"e":299.08,"t":"So much red tape."},{"s":304.54,"e":310.38,"t":"I think you then have to draw up a detailed plan of where you're digging and then measure the limits."},{"s":310.52,"e":313.9,"t":"And this is all before you actually start digging."},{"s":314.22,"e":316.34,"t":"Okay, so far so good."},{"s":324.58,"e":329.24,"t":"Anything that you don't think is useful, you leave in place on the site. ."},{"s":345.44,"e":351.9,"t":"That's right and remember to leave the tools and site hut as you would expect to find them."},{"s":352.56,"e":355.4,"t":"Looks like we've learned something after all."}],"4":[{"s":78.58,"e":86.54,"t":"I've just arrived back from my field trip, and Professor Martin has asked me to tell you about it today in our research forum."},{"s":86.24,"e":91.6,"t":"As many of you know already, my dissertation relates to crocodile behavior."},{"s":91.84,"e":97.56,"t":"My specialty is the saltwater crocodile, which is much larger than the freshwater crocodile."},{"s":97.7,"e":105.2,"t":"I've just come back from the northern territory, where I've been part of a groundbreaking study, observing crocodile movements."},{"s":105.32,"e":114.0,"t":"Ah, it's not the only time crocodile movements have been followed, but this study is unique, because we tracked crocodiles using a satellite."},{"s":113.7,"e":120.32,"t":"Up until now, studies like this one have only been able to track crocodile movements using radio."},{"s":131.0,"e":135.04,"t":"So, you might be wondering why we chose to track crocodiles."},{"s":135.32,"e":139.22,"t":"Well, crocodile attacks on people and livestock are rare."},{"s":138.92,"e":146.08,"t":"But when they do happen, the government believes that the problem crocodile should be relocated rather than killed."},{"s":146.46,"e":151.3,"t":"But can we be sure that the crocodile won't simply return to the place where it came from?"},{"s":151.46,"e":155.34,"t":"So, we designed a study to try to answer these questions."},{"s":155.9,"e":161.7,"t":"We wanted to establish, firstly, how far crocodiles can travel over a period of time."},{"s":161.9,"e":167.66,"t":"The second thing that we wanted to know was how easy is for crocodiles to navigate."},{"s":167.36,"e":172.34,"t":"Could they find their own way home again if they were moved to another location?"},{"s":172.52,"e":178.62,"t":"Of course, the biggest challenge when observing crocodiles is that they are very secretive animals."},{"s":178.86,"e":184.16,"t":"They stay well away from people if they can, which makes them really difficult to follow."},{"s":189.22,"e":192.84,"t":"I'll give you some information about the design of the study now."},{"s":212.0,"e":215.98,"t":"We were then able to use the tracking data to monitor their movements."},{"s":216.38,"e":221.2,"t":"We used a specially designed transmitter, which we attached to each animal's head."},{"s":221.36,"e":225.06,"t":"The transmitter collected the data and related back to us."},{"s":225.34,"e":228.32,"t":"The results of our study were quite astounding."},{"s":228.02,"e":236.5,"t":"After they were released, each crocodile remained in the release site for some weeks, making random movements around the site each day."},{"s":236.68,"e":241.46,"t":"But then, they each swam home, traveling by the most direct route."},{"s":241.64,"e":248.12,"t":"These crocodiles showed remarkable navigational skills and stamina to swim such long voyages."},{"s":248.8,"e":251.9,"t":"So, what conclusions did we draw from this?"},{"s":251.6,"e":258.46,"t":"Well, we prove that crocodiles are clearly capable of making marathon swims to find their way home."},{"s":258.7,"e":262.3,"t":"This meant that the current policy should be reconsidered."},{"s":262.56,"e":266.14,"t":"You might be wondering how the crocodiles managed to get home."},{"s":266.36,"e":273.5,"t":"We concluded that they used factors such as sight and smell, as well as their position to the sun, to point their way."},{"s":273.7,"e":280.38,"t":"It's a little known fact that crocodiles are more closely related to birds than they are to any other reptile."},{"s":281.6,"e":286.26,"t":"it's possible that they use the same system to negotiate long journeys."},{"s":286.74,"e":288.84,"t":"Now that the study has been completed."}]}};
